//! Bake the contributor credits into the binary as static Rust tables (craftrules
//! standards/contributors.md), through craft-credits: contributors/contributors.json (commit stats,
//! generated by craftrules scripts/contributors.py) and contributors/people.toml (the names people
//! chose for themselves, used only when the JSON says the entry was verified). Nothing is read at
//! run time; a missing or malformed file gives empty tables (or no names) and a warning.

fn main() {
    craft_credits::build::write_credits(&std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../contributors"));
}
